#include <psxgpu.h>
#include <psxgte.h>
#include "world3d.h"

typedef struct{short x,y,z;} V3;
static MATRIX cam;
static int ready=0;
static void quad(uint32_t*ot,char**pk,int depth,V3 a,V3 b,V3 c,V3 d,int r,int g,int bl){POLY_F4*p=(POLY_F4*)*pk;VECTOR va={a.x,a.y,a.z,0},vb={b.x,b.y,b.z,0},vc={c.x,c.y,c.z,0},vd={d.x,d.y,d.z,0};long s0,s1,s2,s3,flag;setPolyF4(p);setRGB0(p,r,g,bl);gte_ldv3(&va,&vb,&vc);gte_rtpt();gte_stsxy0(&s0);gte_stsxy1(&s1);gte_stsxy2(&s2);gte_ldv0(&vd);gte_rtps();gte_stsxy(&s3);setXY4(p,(short)s0,(short)(s0>>16),(short)s1,(short)(s1>>16),(short)s2,(short)(s2>>16),(short)s3,(short)(s3>>16));gte_stflg(&flag);if(!(flag&0x80000000)){addPrim(ot+depth,p);*pk+=sizeof(POLY_F4);}}
static void box(uint32_t*ot,char**pk,int x,int y,int z,int w,int h,int d,int r,int g,int b){V3 a={x,y,z},bb={x+w,y,z},c={x+w,y+h,z},dd={x,y+h,z};V3 e={x,y,z+d},f={x+w,y,z+d},gg={x+w,y+h,z+d},hh={x,y+h,z+d};quad(ot,pk,4,a,bb,c,dd,r,g,b);quad(ot,pk,4,e,hh,gg,f,r-8,g-8,b-8);quad(ot,pk,3,a,e,f,bb,r+8,g+8,b+8);quad(ot,pk,3,dd,c,gg,hh,r-15,g-15,b-15);quad(ot,pk,3,a,dd,hh,e,r-10,g-10,b-10);quad(ot,pk,3,bb,f,gg,c,r-5,g-5,b-5);}
void world3d_init(void){VECTOR t={0,0,0,0};SVECTOR rot={160,0,0,0};RotMatrix(&rot,&cam);TransMatrix(&cam,&t);SetRotMatrix(&cam);SetTransMatrix(&cam);SetGeomOffset(160,112);SetGeomScreen(260);ready=1;}
void world3d_draw_station(int px,int py,int facing,int tick,uint32_t*ot,char**pk){int i;V3 f0={-720,190,450},f1={720,190,450},f2={720,190,1800},f3={-720,190,1800};V3 wall0={-720,-380,1750},wall1={720,-380,1750},wall2={720,190,1750},wall3={-720,190,1750};if(!ready)world3d_init();SetRotMatrix(&cam);SetTransMatrix(&cam);quad(ot,pk,6,f0,f3,f2,f1,30,34,45);quad(ot,pk,6,wall0,wall1,wall2,wall3,18,23,38);for(i=0;i<7;i++)box(ot,pk,-650+i*210,-330,1680,28,520,40,62,65,73);box(ot,pk,-620,125,720,1240,55,700,74,65,52);box(ot,pk,-600,70,1180,310,55,150,70,62,56);box(ot,pk,290,70,1180,310,55,150,70,62,56);box(ot,pk,-55,-290,1620,110,110,35,175,158,110);box(ot,pk,-360,-160,1660,260,80,35,31,55,70);box(ot,pk,100,-160,1660,260,80,35,31,55,70);box(ot,pk,-530,-60,1300,240,55,80,83,67,54);box(ot,pk,290,-60,1300,240,55,80,83,67,54);for(i=0;i<8;i++)box(ot,pk,-650+i*185,176,520,110,12,1050,48,43,37);/* Moko low-poly proxy */{int mx=(px-160)*4;int mz=720+(205-py)*5;box(ot,pk,mx-38,70,mz,76,105,58,111,65,154);box(ot,pk,mx-45,20,mz+4,90,65,62,137,83,180);box(ot,pk,mx-32,-20,mz+12,18,55,18,202,116,150);box(ot,pk,mx+14,-20,mz+12,18,55,18,202,116,150);box(ot,pk,mx-25,172,mz-3,22,22,50,205,185,154);box(ot,pk,mx+7,172,mz-3,22,22,50,205,185,154);box(ot,pk,mx-18,102,mz-8,36,36,12,190,145,54);} }
